-- 22.11: Humo *7052 оплата 30 000 «IPAK YULI M ULUGBEK» (21:34) ошибочно стала переводом на Ipak *3153: возвращаем расход, заметка «Компы», парная ножка удаляется
UPDATE transactions SET deleted_at=CAST(strftime('%s','now') AS INTEGER)*1000, updated_at=CAST(strftime('%s','now') AS INTEGER)*1000, synced_at=CAST(strftime('%s','now') AS INTEGER)*1000 WHERE type='transfer' AND deleted_at IS NULL AND amount=3000000 AND transfer_group_id=(SELECT t.transfer_group_id FROM transactions t JOIN accounts a ON a.id=t.account_id WHERE t.user_id=(SELECT v FROM meta WHERE k='owner_uid') AND a.card_last4='7052' AND t.type='transfer' AND t.amount=-3000000 AND t.deleted_at IS NULL AND t.occurred_at BETWEEN CAST(strftime('%s','2026-11-22 16:25:00') AS INTEGER)*1000 AND CAST(strftime('%s','2026-11-22 16:45:00') AS INTEGER)*1000 LIMIT 1);
